	private void btnAc_Click(object sender, EventArgs e)
	{
		//IL_0020: Unknown result type (might be due to invalid IL or missing references)
		//IL_0499: Unknown result type (might be due to invalid IL or missing references)
		if (Operators.CompareString(UserPrint, "Y", false) != 0)
		{
			Interaction.MsgBox((object)"You Have No Print Rights.....", (MsgBoxStyle)0, (object)null);
			return;
		}
		lblBook.Text = "Account Refersh";
		((Control)ProgressBar1).Visible = true;
		ProgressBar1.Value = 0;
		ProgressBar1.Maximum = 119;
		DC_Main.ExeQuteDc("UPDATE BOOK_DATA SET DATA_TYPE = 'A' WHERE DATA_TYPE IS NULL OR DATA_TYPE = ''");
		DC_Main.ExeQuteDc("UPDATE BOOK_DETL SET DATA_TYPE = 'A' WHERE DATA_TYPE IS NULL OR DATA_TYPE = ''");
		DC_Main.ExeQuteDc("UPDATE CASH_DATA SET CLR_DATE = VCH_DATE WHERE CLR_DATE IS NULL");
		DC_Main.ExeQuteDc("DELETE FROM BANK_RECONCILE");
		DC_Main.RsQry = "INSERT INTO BANK_RECONCILE(CO_CODE,LC_CODE,LEDR_KEY,CLR_DATE) SELECT A.CO_CODE,A.LC_CODE,LEDR_KEY,CLR_DATE FROM  AC_DATA AS A LEFT JOIN AC_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.AC_CODE = B.AC_CODE  WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "' AND B.AC_GR IN ('02','22','23')";
		DC_Main.ExeQuteDc(DC_Main.RsQry);
		AcRefresh();
		DC_Main.RsQry = "SELECT CO_BOOK,BOOK_TBL_NAME FROM BOOK_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CUR_USE = 'Y' AND BOOK_TBL_NAME <> '' GROUP BY CO_BOOK,BOOK_TBL_NAME  ORDER BY CO_BOOK ";
		DC_Main.Tbl = DC_Main.OpenRecordSetDc(DC_Main.RsQry);
		DC_Main.X = 0;
		checked
		{
			while (DC_Main.X < DC_Main.Tbl.Rows.Count)
			{
				object obj = DC_Main.Tbl.Rows[DC_Main.X]["BOOK_TBL_NAME"];
				if (Operators.ConditionalCompareObjectEqual(obj, (object)"LDR_ADJ_DATA", false))
				{
					Ac_Tax.Vch_Remark(Conversions.ToString(DC_Main.Tbl.Rows[DC_Main.X]["CO_BOOK"]), "", 1);
				}
				else if (Operators.ConditionalCompareObjectEqual(obj, (object)"ITM_LOT_DETL", false))
				{
					Ac_Tax.Vch_Remark(Conversions.ToString(DC_Main.Tbl.Rows[DC_Main.X]["CO_BOOK"]), "", 2);
				}
				else if (Conversions.ToBoolean((object)(Conversions.ToBoolean(Operators.CompareObjectEqual(obj, (object)"CASH_DATA", false)) || Conversions.ToBoolean(Operators.CompareObjectEqual(obj, (object)"CONTRA_DATA", false)) || Conversions.ToBoolean(Operators.CompareObjectEqual(obj, (object)"BUL_DATA", false)) || Conversions.ToBoolean(Operators.CompareObjectEqual(obj, (object)"AD_DATA", false)))))
				{
					Ac_Tax.Vch_Remark(Conversions.ToString(DC_Main.Tbl.Rows[DC_Main.X]["CO_BOOK"]), "", 3);
				}
				else
				{
					Ac_Tax.Vch_Remark(Conversions.ToString(DC_Main.Tbl.Rows[DC_Main.X]["CO_BOOK"]), "", 0);
				}
				DC_Main.X++;
			}
			DC_Main.RsQry = "SELECT * FROM BANK_RECONCILE WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' ORDER BY LEDR_KEY";
			DC_Main.Tbl = DC_Main.OpenRecordSetDc(DC_Main.RsQry);
			DC_Main.X = 0;
			while (DC_Main.X < DC_Main.Tbl.Rows.Count)
			{
				if (Information.IsDBNull(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.X]["CLR_DATE"])))
				{
					DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("UPDATE AC_DATA SET CLR_DATE = NULL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND LEDR_KEY = '"), DC_Main.Tbl.Rows[DC_Main.X]["LEDR_KEY"]), (object)"'"));
					DC_Main.ExeQuteDc(DC_Main.RsQry);
				}
				else
				{
					DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("UPDATE AC_DATA SET CLR_DATE = '" + Strings.Format(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.X]["CLR_DATE"]), "MM/dd/yyyy") + "' WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND LEDR_KEY = '"), DC_Main.Tbl.Rows[DC_Main.X]["LEDR_KEY"]), (object)"'"));
					DC_Main.ExeQuteDc(DC_Main.RsQry);
				}
				DC_Main.X++;
			}
			Interaction.MsgBox((object)"Account Refersh Process Complete.", (MsgBoxStyle)64, (object)null);
		}
	}

	private void AcRefresh()
	{
		if (((Operators.CompareString(DC_Main.SSRegSrNo, "VK106NEVK", false) == 0) | (Operators.CompareString(DC_Main.SSRegSrNo, "VK128NEVK", false) == 0)) & (Operators.CompareString(DC_Main.MCo_year, "2024-2025", false) == 0))
		{
			DC_Main.ExeQuteDc("DELETE FROM AC_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_BOOK NOT IN ('888','000') ");
		}
		else
		{
			DC_Main.ExeQuteDc("DELETE FROM AC_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_BOOK <> '888'");
		}
		DC_Main.ExeQuteDc("DELETE FROM ROJ_MEL_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "'");
		DC_Main.ExeQuteDc("DELETE FROM TAX_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "'");
		DC_Main.ExeQuteDc("DELETE FROM DHRN_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "'");
