	private void btnStock_Click(object sender, EventArgs e)
	{
		//IL_0020: Unknown result type (might be due to invalid IL or missing references)
		//IL_1ce1: Unknown result type (might be due to invalid IL or missing references)
		if (Operators.CompareString(UserPrint, "Y", false) != 0)
		{
			Interaction.MsgBox((object)"You Have No Print Rights.....", (MsgBoxStyle)0, (object)null);
			return;
		}
		lblBook.Text = "Stock Refersh";
		DC_Main.RsQry = "SELECT TAG_NO,ITM_NWT,ITM_TOUCH,ITM_WEST_PRC,ITM_FINE,VCH_SRNO FROM BAR_DETL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND (ITM_TOUCH + ITM_WEST_PRC) <> 0 AND ITM_FINE <= 0 ORDER BY TAG_NO";
		DC_Main.Tbl = DC_Main.OpenRecordSetDc(DC_Main.RsQry);
		DC_Main.M = 0;
		checked
		{
			while (DC_Main.M < DC_Main.Tbl.Rows.Count)
			{
				double num = 0.0;
				if (Conversions.ToBoolean(Operators.AndObject(Operators.CompareObjectNotEqual(DC_Main.Tbl.Rows[DC_Main.M]["ITM_NWT"], (object)0, false), (object)(Conversion.Val(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.M]["ITM_TOUCH"])) + Conversion.Val(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.M]["ITM_WEST_PRC"])) != 0.0))))
				{
					num = Conversion.Val(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.M]["ITM_NWT"])) * (Conversion.Val(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.M]["ITM_TOUCH"])) + Conversion.Val(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.M]["ITM_WEST_PRC"]))) / 100.0;
				}
				if (Operators.ConditionalCompareObjectLessEqual(DC_Main.Tbl.Rows[DC_Main.M]["ITM_FINE"], (object)0, false))
				{
					DC_Main.ExeQuteDc(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("UPDATE BAR_DETL SET ITM_FINE = " + Conversions.ToString(num) + " WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND TAG_NO = '"), DC_Main.Tbl.Rows[DC_Main.M]["TAG_NO"]), (object)"' AND VCH_SRNO = "), DC_Main.Tbl.Rows[DC_Main.M]["VCH_SRNO"]), (object)" ")));
				}
				DC_Main.ExeQuteDc(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("UPDATE SL_DETL_RTN SET ITM_FINE  = " + Conversions.ToString(num) + " WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND TAG_NO = '"), DC_Main.Tbl.Rows[DC_Main.M]["TAG_NO"]), (object)"' AND VCH_SRNO = "), DC_Main.Tbl.Rows[DC_Main.M]["VCH_SRNO"]), (object)" ")));
				DC_Main.M++;
			}
			DC_Main.Tbl.Rows.Clear();
			DC_Main.Tbl.Columns.Clear();
			if (Operators.CompareString(Module_Save.MsRendomTag, "Y", false) != 0)
			{
				DC_Main.ExeQuteDc("UPDATE BAR_DETL SET TAG_SRNO = 1 WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND TAG_NO <> 'N'  AND LEN(TAG_NO) > 1 AND CO_BOOK = '218'");
				DC_Main.ExeQuteDc("UPDATE BAR_DETL SET TAG_NO = 'N' WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND TAG_NO = ''");
				if (Operators.CompareString(DC_Main.MsVbImport, "Y", false) == 0)
				{
					DC_Main.ExeQuteDc("UPDATE BAR_DETL SET TAG_SRNO = RIGHT(TAG_NO,4) WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND TAG_NO <> 'N'  AND LEN(TAG_NO) > 6 AND TAG_SRNO = 0 AND  ISNUMERIC(RIGHT(TAG_NO, 4)) = 1 ");
				}
				else
				{
					DC_Main.ExeQuteDc("UPDATE BAR_DETL SET TAG_SRNO = RIGHT(TAG_NO,5) WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND TAG_NO <> 'N'  AND LEN(TAG_NO) > 7 AND TAG_SRNO = 0 AND  ISNUMERIC(RIGHT(TAG_NO, 5)) = 1 ");
