			DC_Main.RsQry = "UPDATE B SET B.ISU_REC = 'Y', B.ITM_PCS = A.ITM_PCS, B.ISU_YRCD = A.CO_YEAR, B.ISU_DBCD = A.CO_BOOK, B.ISU_NO = A.VCH_NO, B.ISU_SRNO = A.SR_NO  FROM APR_DETL A INNER JOIN APR_DETL B ON B.CO_CODE = A.CO_CODE AND B.LC_CODE = A.LC_CODE AND B.CO_YEAR = A.ISU_YRCD AND B.CO_BOOK = A.ISU_DBCD AND B.VCH_NO = A.ISU_NO AND B.OLD_SRNO = A.ISU_SRNO  WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "' AND A.CO_YEAR = '" + DC_Main.MCo_year + "' AND A.BOOK_NAME = 'EMP REC' AND A.TAG_NO <> 'N'";
			DC_Main.ExeQuteDc(DC_Main.RsQry);
			DC_Main.RsQry = "UPDATE B SET B.EMP_SALE = 'Y',B.ISU_REC = 'Y',ITM_PCS = A.ITM_PCS,B.ISU_NO = A.VCH_NO,B.ISU_YRCD = A.CO_YEAR,B.ISU_DBCD = A.CO_BOOK,B.ISU_SRNO = A.OLD_SRNO  FROM RATE_CUT_ISU AS A,APR_DETL AS B WHERE A.CO_CODE = B.CO_CODE And  A.LC_CODE = B.LC_CODE And A.TAG_NO = B.TAG_NO And A.VCH_SRNO = B.VCH_SRNO AND A.BOOK_NAME = 'TOUR SALES' AND B.BOOK_NAME = 'EMP ISU' AND A.TAG_NO <> 'N' AND A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "'";
			DC_Main.ExeQuteDc(DC_Main.RsQry);
			DC_Main.RsQry = "UPDATE B SET B.EMP_ISU = 'Y' FROM APR_DETL AS A,BAR_DETL AS B WHERE A.CO_CODE = B.CO_CODE And  A.LC_CODE = B.LC_CODE And A.TAG_NO = B.TAG_NO And A.VCH_SRNO = B.VCH_SRNO AND A.BOOK_NAME = 'EMP ISU' AND A.ISU_REC = 'N' AND A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "'";
			DC_Main.ExeQuteDc(DC_Main.RsQry);
			if (Operators.CompareString(DC_Main.MsStockRptView, "NEW", false) == 0)
			{
				DC_Main.RsQry = "UPDATE SL_DETL SET TAG_GWT = ITM_GWT WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND TAG_GWT = 0";
				DC_Main.ExeQuteDc(DC_Main.RsQry);
				DC_Main.RsQry = "UPDATE SL_DETL SET TAG_NWT = ITM_NWT WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND TAG_NWT = 0";
				DC_Main.ExeQuteDc(DC_Main.RsQry);
			}
			DC_Main.ExeQuteDc("UPDATE LBR_REC_DETL SET TAG_NO = 'N' WHERE TAG_NO = ''");
			if (Operators.CompareString(DC_Main.SSRegSrNo, "VK178NEVK", false) == 0)
			{
				DC_Main.ExeQuteDc("UPDATE BAR_CAN_DETL SET TBL_POSTING = 'Y' WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND CO_BOOK = '133' AND TBL_POSTING = ''");
			}
			((Control)ProgressBar1).Visible = true;
			ProgressBar1.Value = 0;
			ProgressBar1.Maximum = 72;
			Application.DoEvents();
			StockRefresh();
			if ((Operators.CompareString(DC_Main.MsSoftType, "A", false) == 0) | (Operators.CompareString(DC_Main.MsSoftType, "E", false) == 0))
			{
				DC_Main.RsQry = "UPDATE MAIN_STOCK SET MAIN_STOCK.DATA_TYPE = B.DATA_TYPE FROM MAIN_STOCK,BAR_DETL AS B WHERE B.CO_CODE = MAIN_STOCK.CO_CODE AND B.TAG_NO = MAIN_STOCK.TAG_NO AND B.VCH_SRNO = MAIN_STOCK.VCH_SRNO AND B.CO_CODE = '" + DC_Main.MCo_code + "' AND B.LC_CODE = '" + DC_Main.MLc_code + "' AND B.CO_YEAR = '" + DC_Main.MCo_year + "' AND MAIN_STOCK.ITM_SIGN = '+' ";
				DC_Main.ExeQuteDc(DC_Main.RsQry);
			}
			DC_Main.ExeQuteDc("UPDATE MAIN_STOCK SET ITM_SIZE = '' WHERE ITM_SIZE IS NULL");
			DC_Main.ExeQuteDc("UPDATE MAIN_STOCK SET DESIGN_NO = '' WHERE DESIGN_NO IS NULL");
			if (Operators.CompareString(DC_Main.SSRegSrNo, "VS021NPVS", false) == 0)
			{
				DC_Main.RsQry = "Select A.IT_CODE, SUM(CASE WHEN ITM_SIGN = '+' THEN KR_NWT ELSE 0 END) AS TotNetWt,SUM(CASE WHEN ITM_SIGN = '+' THEN KR_FINE ELSE 0 END) AS TotFine FROM MAIN_STOCK AS A INNER JOIN ITEM_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.IT_CODE = B.IT_CODE WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE ='" + DC_Main.MLc_code + "' AND A.CO_YEAR = '" + DC_Main.MCo_year + "' AND B.IT_TYPE IN ('G','S') AND A.TR_TYPE IN ('P','I') GROUP BY A.IT_CODE ";
				DC_Main.Tbl = DC_Main.OpenRecordSetDc(DC_Main.RsQry);
				DC_Main.M = 0;
				while (DC_Main.M < DC_Main.Tbl.Rows.Count)
				{
					if (Conversion.Val(RuntimeHelpers.GetObjectValue(DC_Main.Tbl.Rows[DC_Main.M]["TotFine"])) == 0.0)
					{
						DC_Main.ExeQuteDc(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("UPDATE MAIN_STOCK SET KR_NWT = ITM_NWT WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND KR_FINE = 0 AND IT_CODE = '"), DC_Main.Tbl.Rows[DC_Main.M]["IT_CODE"]), (object)"'")));
						DC_Main.ExeQuteDc(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("UPDATE MAIN_STOCK SET KR_FINE = ITM_NWT WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND KR_FINE = 0 AND IT_CODE = '"), DC_Main.Tbl.Rows[DC_Main.M]["IT_CODE"]), (object)"'")));
					}
					DC_Main.M++;
				}
				DC_Main.Tbl.Rows.Clear();
				DC_Main.Tbl.Columns.Clear();
			}
			Interaction.MsgBox((object)"Stock Refresh Process Complete.", (MsgBoxStyle)64, (object)null);
		}
	}

	private void StockRefresh()
	{
		if (Operators.CompareString(DC_Main.MsCurDayPosting, "Y", false) == 0)
		{
			DateTime t = Conversions.ToDate(Strings.Format((object)Conversions.ToDate(mFromDt.Text), "dd/MM/yyyy"));
			if (DateTime.Compare(t, DC_Main.MOp_dt.AddDays(-1.0)) < 0)
			{
				mFromDt.Text = Strings.Format((object)DC_Main.MOp_dt.AddDays(-1.0), "dd/MM/yyyy");
			}
			DC_Main.ExeQuteDc("DELETE FROM MAIN_STOCK WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND VCH_DATE >= '" + Strings.Format((object)Conversions.ToDate(mFromDt.Text), "MM/dd/yyyy") + "' AND VCH_DATE <= '" + Strings.Format((object)Conversions.ToDate(mToDt.Text), "MM/dd/yyyy") + "'");
			DC_Main.MsPostingDate = "AND A.VCH_DATE >= '" + Strings.Format((object)Conversions.ToDate(mFromDt.Text), "MM/dd/yyyy") + "' AND A.VCH_DATE <= '" + Strings.Format((object)Conversions.ToDate(mToDt.Text), "MM/dd/yyyy") + "'";
		}
		else
		{
			DC_Main.ExeQuteDc("DELETE FROM MAIN_STOCK WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "'");
			DC_Main.MsPostingDate = "";
		}
		DC_Main.ExeQuteDc("DELETE FROM LOT_DETL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND CO_YEAR = '" + DC_Main.MCo_year + "' AND LC_CODE = '" + DC_Main.MLc_code + "'");
