				}
				DC_Main.RsQry = "UPDATE BAR_DETL SET TAG_SRNO = SUBSTRING(TAG_NO,4,4) WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND LEN(TAG_NO) = 7 ";
				DC_Main.ExeQuteDc(DC_Main.RsQry);
			}
		}
		else
