					(progressBar = ProgressBar1).Value = progressBar.Value + 1;
					Application.DoEvents();
				}
			}
		}
		Interaction.MsgBox((object)"Opning Balance is Update Please Data Refresh...", (MsgBoxStyle)64, (object)null);
	}

